-- su — Лекция 2. Строевые приёмы и движения: схем 1
UPDATE lectures SET body = replace(body, 'Повороты кругом (на 1/2 круга), налево (на 1/4 круга), пол-оборота налево (на 1/8 круга) производятся в сторону левой руки на левом каблуке и на правом носке; направо и пол-оборота направо - в сторону правой руки на правом каблуке и на левом носке. Повороты выполняются в два приема: первый прием - повернуться, сохраняя правильное положение корпуса, и, не сгибая ног в коленях, перенести тяжесть тела на впереди стоящую ногу; второй прием - кратчайшим путем приставить другую ногу.', 'Повороты кругом (на 1/2 круга), налево (на 1/4 круга), пол-оборота налево (на 1/8 круга) производятся в сторону левой руки на левом каблуке и на правом носке; направо и пол-оборота направо - в сторону правой руки на правом каблуке и на левом носке. Повороты выполняются в два приема: первый прием - повернуться, сохраняя правильное положение корпуса, и, не сгибая ног в коленях, перенести тяжесть тела на впереди стоящую ногу; второй прием - кратчайшим путем приставить другую ногу.

